<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>Sign in</title><style>body{font:16px system-ui;background:#f3f6fb;display:grid;min-height:100vh;place-items:center}.card{background:white;padding:32px;border-radius:14px;width:min(420px,90vw);box-shadow:0 10px 40px #15233b15}.field{margin:18px 0}label{display:block}input{width:100%;padding:12px;box-sizing:border-box}.btn{padding:12px;background:#078565;color:white;border:0;border-radius:7px;width:100%}a{color:#2859aa}</style></head><body><div class='card'><h1>Sign in</h1><form method='post' action='{{ route('login') }}'>@csrf<div class='field'><label>Email</label><input type='email' name='email' required></div><div class='field'><label>Password</label><input type='password' name='password' required></div><button class='btn'>Sign in</button></form><p>New here? <a href='{{ route('register') }}'>Create an account</a></p></div></body></html>